Scripts.OnLoad:
this:SetText("Description: e.g., Fast run, need keys");
this:SetTextColor(0.7, 0.7, 0.7, 1);
this:SetAutoFocus(false);

Scripts.OnEditFocusGained:
if string.find(this:GetText(), "e.g.,") then
    this:SetText("");
    this:SetTextColor(1, 1, 1, 1);
end

Scripts.OnEditFocusLost:
if this:GetText() == "" then
    this:SetText("Description: e.g., Fast run, need keys");
    this:SetTextColor(0.7, 0.7, 0.7, 1);
end

Scripts.OnEditFocusGained:
if string.find(this:GetText(), "Discord") then
    this:SetText("");
    this:SetTextColor(1, 1, 1, 1);
end

Scripts.OnEditFocusLost:
if this:GetText() == "" then
    this:SetText("Discord/TS...");
    this:SetTextColor(0.7, 0.7, 0.7, 1);
end

Scripts.OnLoad:
-- Set texture paths for role icons using proper WoW 1.12 paths
if GroupFinderFrameRightPanelCreateViewTankIcon then
    GroupFinderFrameRightPanelCreateViewTankIcon:SetTexture("Interface\\Icons\\Ability_Defend");
end
if GroupFinderFrameRightPanelCreateViewHealerIcon then
    GroupFinderFrameRightPanelCreateViewHealerIcon:SetTexture("Interface\\Icons\\Spell_Holy_Heal");
end
if GroupFinderFrameRightPanelCreateViewDPSIcon then
    GroupFinderFrameRightPanelCreateViewDPSIcon:SetTexture("Interface\\Icons\\Ability_DualWield");
end

